import { build } from 'esbuild';
import { writeFileSync, readFileSync } from 'fs';
import { fileURLToPath } from 'url';
import { dirname, resolve } from 'path';

const __dirname = dirname(fileURLToPath(import.meta.url));
const outfile = resolve(__dirname, '../src/utils/tiptapBundle.js');

const result = await build({
    stdin: {
        contents: `
import { Editor } from '@tiptap/core';
import StarterKit from '@tiptap/starter-kit';
import TiptapImage from '@tiptap/extension-image';
import TextAlign from '@tiptap/extension-text-align';

window.__TiptapEditor = Editor;
window.__TiptapExtensions = { StarterKit, TiptapImage, TextAlign };
`,
        resolveDir: resolve(__dirname, '..'),
    },
    bundle: true,
    format: 'iife',
    minify: true,
    platform: 'browser',
    write: false,
    define: {
        'process.env.NODE_ENV': '"production"',
    },
});

const bundleCode = result.outputFiles[0].text;

// JS 모듈로 래핑해서 RN에서 import 가능하도록
const moduleContent = `// Auto-generated by scripts/build-tiptap-bundle.mjs — DO NOT EDIT
export default ${JSON.stringify(bundleCode)};
`;

writeFileSync(outfile, moduleContent, 'utf8');
console.log(`✓ Tiptap bundle written to ${outfile} (${(bundleCode.length / 1024).toFixed(1)} KB)`);
